import { readFileSync } from 'node:fs';
import {
  generatePartialResults,
  type SyntheticElectorate,
} from './synthetic-data.js';
import type { ElectorateResults } from '@election-night/core/types';

/**
 * The mock replays real cycles, not invented ones.
 *
 * `mock-election-data.json` is generated by
 * `scripts/build-mock-election-data.mjs` from the Commission's published
 * results: the 2020 and 2023 archives, and the 2026 live media feed. Keeping
 * the fixture checked in means the mock stays offline and a replay is
 * deterministic — the same command always serves the same candidates and the
 * same seat-by-seat tendencies.
 *
 * The fixture stores final totals. `buildMockElectionSet` scales them into four
 * partial counts; it never changes who is ahead in a seat.
 */
type FixtureParty = {
  pNo: number;
  abbrev: string;
  name: string;
  registered: boolean;
};

type FixtureElectorate = {
  eNo: number;
  name: string;
  kind: 'general' | 'maori';
};

type FixtureCandidate = {
  cNo: number;
  name: string;
  /** The feed's electorate number, 0 for a list-only candidate. */
  eNo: number;
  /** 0 for an independent. */
  pNo: number;
  listNo: number;
};

type FixtureElectorateResult = {
  votesCounted: number;
  enrolment: number | null;
  partyVotes: Record<string, number>;
  candidateVotes: Record<string, number>;
};

type FixtureElectionParty = {
  pNo: number;
  votes: number;
  percentVotes: number;
  listSeats: number;
  electorateSeats: number;
  totalSeats: number;
};

type FixtureCycle = {
  source: string;
  pollingDate: string;
  parties: FixtureParty[];
  electorates: FixtureElectorate[];
  candidates: FixtureCandidate[];
  results: Record<string, FixtureElectorateResult>;
  election: {
    totalVotesCast: number;
    percentVotesCast: number;
    totalElectoratesFinal: number;
    percentElectoratesFinal: number;
    totalMinimalVotes: number;
    totalSpecialVotes: number;
    parties: FixtureElectionParty[];
  };
};

type Fixture = {
  _comment: string;
  cycles: Record<string, FixtureCycle>;
};

const FIXTURE: Fixture = JSON.parse(
  readFileSync(new URL('./mock-election-data.json', import.meta.url), 'utf8')
) as Fixture;

/** One party as the mock publishes it in `parties.xml`. */
export type MockParty = {
  pNo: number;
  abbrev: string;
  name: string;
  registered: boolean;
};

/** One candidate as the mock publishes it in `candidates.xml`. */
export type MockCandidate = {
  cNo: number;
  name: string;
  /** The mock's electorate number; 0 for a list-only candidate. */
  eNo: number;
  /** 0 for an independent. */
  pNo: number;
  listNo: number;
};

export type CandidateInfo = { name: string; party?: string; cNo: number };

export type MockElectorate = {
  /** The mock's own numbering, general first and then Māori. */
  eNo: number;
  name: string;
  candidates: CandidateInfo[];
};

/** Election cycles the mock can replay. */
export type MockElectionYear = '2020' | '2023' | '2026';

export const MOCK_ELECTION_YEARS: readonly MockElectionYear[] = [
  '2020',
  '2023',
  '2026',
];

export const DEFAULT_MOCK_ELECTION_YEAR: MockElectionYear = '2023';

export function isMockElectionYear(value: string): value is MockElectionYear {
  return (MOCK_ELECTION_YEARS as readonly string[]).includes(value);
}

