/** Share of an electorate's count reported at each stage. */
type StagePct = { early: number; mid: number; late: number; full: number };

/**
 * Counting speed profiles. A seat's profile is chosen from its name and cycle,
 * so the same replay always reports the same seats first, and the ordering
 * survives a restart. Every profile is strictly increasing and reaches 100% at
 * the final stage.
 *
 * The real feed publishes a count per voting place, not a percentage, so the
 * mock has to invent the pace; it no longer invents the result. Keeping several
 * profiles means the early stage still shows a mix of close and finished seats.
 */
const STAGE_PROFILES: StagePct[] = [
  { early: 0.12, mid: 0.36, late: 0.78, full: 1 },
  { early: 0.18, mid: 0.44, late: 0.84, full: 1 },
  { early: 0.26, mid: 0.52, late: 0.9, full: 1 },
  { early: 0.34, mid: 0.61, late: 0.93, full: 1 },
  { early: 0.45, mid: 0.7, late: 0.96, full: 1 },
  { early: 0.58, mid: 0.8, late: 0.98, full: 1 },
];

/** FNV-1a, so a seat's profile is stable across processes. */
function hashString(value: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < value.length; i++) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function stagePctFor(year: MockElectionYear, name: string): StagePct {
  return STAGE_PROFILES[hashString(`${year}:${name}`) % STAGE_PROFILES.length]!;
}

function partyNameByNumber(fixture: FixtureCycle): Map<number, string> {
  return new Map(fixture.parties.map((party) => [party.pNo, party.name]));
}

/**
 * Build the mock's electorates and candidates for one cycle.
 *
 * The fixture keeps the Commission's own numbers; the mock renumbers
 * electorates into the order the boundary manifest uses. Candidate names are
 * preserved exactly, including list-only candidates (electorate 0), which is
 * what makes the party-list page carry the real ranking.
 */
function buildElectorates(
  fixture: FixtureCycle,
  set: { general: string[]; maori: string[] }
): {
  electorates: MockElectorate[];
  listCandidates: MockCandidate[];
} {
  const names = [...set.general, ...set.maori];
  const fixtureNameByENo = new Map(
    fixture.electorates.map((electorate) => [electorate.eNo, electorate.name])
  );
  const partyNameByNo = partyNameByNumber(fixture);

  const byElectorate = new Map<string, CandidateInfo[]>();
  const listCandidates: MockCandidate[] = [];

  for (const candidate of fixture.candidates) {
    if (candidate.eNo === 0) {
      listCandidates.push({
        cNo: candidate.cNo,
        name: candidate.name,
        eNo: 0,
        pNo: candidate.pNo,
        listNo: candidate.listNo,
      });
      continue;
    }

    const name = fixtureNameByENo.get(candidate.eNo);
    if (!name) continue;
    const list = byElectorate.get(name) ?? [];
    list.push({
      name: candidate.name,
      party: candidate.pNo > 0 ? partyNameByNo.get(candidate.pNo) : undefined,
      cNo: candidate.cNo,
    });
    byElectorate.set(name, list);
  }

  for (const name of names) {
    if (!byElectorate.has(name)) {
      throw new Error(
        `Mock fixture has no candidates for ${name}; regenerate mock-election-data.json`
      );
    }
  }

  return {
    electorates: names.map((name, index) => ({
      eNo: index + 1,
      name,
      candidates: byElectorate.get(name) ?? [],
    })),
    listCandidates,
  };
}

/** The candidate's own party, without inventing one for an independent. */
function buildSyntheticElectorate(
  electorate: MockElectorate,
  fixture: FixtureCycle,
  fixtureENo: number
): SyntheticElectorate {
  const result = fixture.results[String(fixtureENo)];
  if (!result) {
    throw new Error(
      `Mock fixture has no result for ${electorate.name} (${fixtureENo}); regenerate mock-election-data.json`
    );
  }

  const partyNameByNo = partyNameByNumber(fixture);
  const candidateVotes = electorate.candidates.map((candidate) => ({
    name: candidate.name,
    party: candidate.party,
    finalVotes: result.candidateVotes[String(candidate.cNo)] ?? 0,
  }));

  const parties = Object.entries(result.partyVotes)
    .map(([pNo, votes]) => ({
      party: partyNameByNo.get(Number(pNo)),
      votes,
    }))
    .filter(
      (entry): entry is { party: string; votes: number } =>
        entry.party !== undefined
    )
    .sort((a, b) => b.votes - a.votes || a.party.localeCompare(b.party));

  return {
    name: electorate.name,
    candidates: candidateVotes,
    parties: parties.map((entry) => entry.party),
    partyVoteFinal: parties.map((entry) => entry.votes),
    totalVotesCast: result.votesCounted,
    enrolment: result.enrolment,
  };
}

function generateStage(
  electorates: SyntheticElectorate[],
  percentages: Map<string, StagePct>,
  stage: keyof StagePct
): ElectorateResults[] {
  return electorates.map((electorate) =>
    generatePartialResults(electorate, percentages.get(electorate.name)![stage])
  );
}

export type MockElectionSet = {
  year: MockElectionYear;
  parties: MockParty[];
  electorates: MockElectorate[];
  /** Party-list-only candidates, published with electorate 0. */
  listCandidates: MockCandidate[];
  /** Every candidate in the feed, electorate and list-only. */
  candidates: MockCandidate[];
  /** One result set per counting stage, each covering every electorate. */
  stages: Record<keyof StagePct, ElectorateResults[]>;
  /** The Commission's own national table, used for the final-stage seats. */
  election: FixtureCycle['election'];
  /** ISO date of polling day for the cycle, used by voting-place timestamps. */
  pollingDate: string;
  /** Enrolled electors per electorate, so turnout stays a real percentage. */
  enrolmentByElectorate: Map<string, number>;
};

/**
 * Build the whole mock feed for one election cycle: electorates, candidates,
 * and the four counting stages.
 *
 * The full stage is the real published result. Earlier stages are those totals
 * scaled down, so a seat that finished Labour 5,000 votes ahead is still Labour
 * 5,000 ahead in proportion at every stage — the mock now differs only in how
 * much has been counted, not in who won.
 */
export function buildMockElectionSet(
  year: MockElectionYear = DEFAULT_MOCK_ELECTION_YEAR
): MockElectionSet {
  const set = MOCK_ELECTORATE_SETS[year];
  const fixture = FIXTURE.cycles[year];
  if (!fixture) {
    throw new Error(
      `No mock fixture for ${year}; run node scripts/build-mock-election-data.mjs`
    );
  }

  const { electorates, listCandidates } = buildElectorates(fixture, set);
  const fixtureENoByName = new Map(
    fixture.electorates.map((electorate) => [electorate.name, electorate.eNo])
  );
  const rawCandidateByNo = new Map(
    fixture.candidates.map((candidate) => [candidate.cNo, candidate])
  );

  const synthetic = electorates.map((electorate) =>
    buildSyntheticElectorate(
      electorate,
      fixture,
      fixtureENoByName.get(electorate.name)!
    )
  );
  const percentages = new Map(
    electorates.map((electorate) => [
      electorate.name,
      stagePctFor(year, electorate.name),
    ])
  );

  return {
    year,
    parties: fixture.parties.map((party) => ({
      pNo: party.pNo,
      abbrev: party.abbrev,
      name: party.name,
      registered: party.registered,
    })),
    electorates,
    listCandidates,
    candidates: [
      ...listCandidates,
      ...electorates.flatMap((electorate) =>
        electorate.candidates.map((candidate) => {
          const raw = rawCandidateByNo.get(candidate.cNo);
          return {
            cNo: candidate.cNo,
            name: candidate.name,
            eNo: electorate.eNo,
            pNo: raw?.pNo ?? 0,
            listNo: raw?.listNo ?? 0,
          };
        })
      ),
    ],
    stages: {
      early: generateStage(synthetic, percentages, 'early'),
      mid: generateStage(synthetic, percentages, 'mid'),
      late: generateStage(synthetic, percentages, 'late'),
      full: generateStage(synthetic, percentages, 'full'),
    },
    election: fixture.election,
    pollingDate: fixture.pollingDate,
    enrolmentByElectorate: new Map(
      synthetic.map((electorate) => [
        electorate.name,
        electorate.enrolment ?? 0,
      ])
    ),
  };
}
